const Button: React.FC<ButtonProps> = ({
    label,
    variant = "primary",
    disabled,
    onClick
}) => {
    return (
        <button
            className={`btn btn-${variant}`}
            disabled={disabled}
            onClick={onClick}
        >
            {label}
        </button>
    );
};

