const Tree: React.FC<TreeProps> = ({ data }) => {
    return (
        <ul>
            {data.map(node => (
                <TreeNode key={node.id} node={node} />
            ))}
        </ul>
    );
};

const TreeNode: React.FC<Props> = ({ node }) => {
    return (
        <li>
            {node.label}
            {node.children && (
                <ul>
                    {node.children.map(child => (
                        <TreeNode key={child.id} node={child} />
                    ))}
                </ul>
            )}
        </li>
    );
};
